import heapq

def match(orders):
    trades = []
    buy_heap = []   # (-price, time, id)
    sell_heap = []  # (price, time, id)
    book = {}       # id -> dict(side, price, qty, time, active)
    time_counter = 0

    def add_to_book(oid, side, price, qty, t):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'time': t, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, t, oid))
        else:
            heapq.heappush(sell_heap, (price, t, oid))

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        time_counter += 1
        t = time_counter

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        remaining = qty
        heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0 and heap:
            top = heap[0]
            if side == 'buy':
                p, tt, rid = top
            else:
                negp, tt, rid = top
                p = -negp

            resting = book.get(rid)
            if resting is None or not resting['active'] or resting['qty'] <= 0:
                heapq.heappop(heap)
                continue

            if price is not None:
                if side == 'buy' and p > price:
                    break
                if side == 'sell' and p < price:
                    break

            trade_qty = min(remaining, resting['qty'])
            if side == 'buy':
                trades.append([oid, rid, p, trade_qty])
            else:
                trades.append([rid, oid, p, trade_qty])

            remaining -= trade_qty
            resting['qty'] -= trade_qty

            if resting['qty'] == 0:
                resting['active'] = False
                heapq.heappop(heap)
            else:
                # resting order not fully consumed, so incoming must be fully filled
                break

        if typ == 'limit' and remaining > 0:
            add_to_book(oid, side, price, remaining, t)
        elif typ == 'limit' and remaining == 0:
            book[oid] = {'side': side, 'price': price, 'qty': 0, 'time': t, 'active': False}
        # ioc and market: discard remainder, do not add to book

    return trades

